"""Freeze the exact expected-cost guard before any new cohort execution."""
from common import ROOT,SRC,OUT,read,save,sha,now


def main():
    assert not(SRC/'protocol.json').exists() and not(OUT/'preparation.json').exists()
    base=read(SRC.parent/'h3bs/protocol.json');pre=read(SRC/'preflight.json');assert pre['counterfactual_parity_and_accept_reject_tie_gates_passed'] and pre['all4096_archived_cases_retained']
    sources=[SRC/f'{name}.py' for name in ['common','compiler','weights','selector','ledger','ledger_gate','synthetic_gate','restriction','policy','counterfactual','cost_gate','prepare','preflight','study','gate','freeze']]+[SRC.parent/'h3at/source.py']
    inputs=[rel for rel in base['source_data_sha256'] if not rel.startswith('research/20261114/loki/h3bs/')]+['research/20261114/loki/h3bs/protocol.json','research/20261114/loki/h3bs/policy.py','results/research/loki/h3bs/summary.json']+[str((SRC/name).relative_to(ROOT)) for name in ['preflight.json','preflight-synthetic-gate.json','preflight-cost-gate.json','LEMMA.md','GUARD_LEMMA.md']]
    p=dict(base)
    p.update(id='H3bt-exact-cost-guarded-online-handoff',frozen_utc=now(),
        hypothesis='The exact posterior expected-cost guard reduces actual total new policy membership calls by at least 2% versus the archived H3br baseline of 10,355: 100 * new_calls <= 98 * 10355, passing maximum 10,147. This is the sole scientific endpoint. The H3bs feasibility-only increase remains falsified and is only a descriptive comparator.',
        routing='At each current set after 0 through 4 newly paid MAP calls, stop if singleton. Otherwise use the unchanged online depth-four posterior tree compiler. If infeasible, continue the unchanged MAP policy while budget remains. If feasible, compute the exact remaining fixed-baseline cost for EVERY candidate, using the remaining 4-used_MAP MAP steps followed by the unchanged posterior tree. Handoff iff the current tree weighted cost is <= that baseline weighted cost. Equality accepts. A rejected guard takes the unchanged next MAP query. At 4 MAP calls a feasible tree must produce equality and handoff. No cost threshold is tuned from cohort outcomes.',
        counterfactual='The baseline evaluator receives current candidates, sorted queried-board indices, remaining MAP budget, and immutable candidate predictions/scores. It recursively follows both predicted label branches of each fixed-baseline MAP query, then obtains terminal posterior-tree leaf depths. Every remaining candidate gets its exact remaining-call count. No actual true identity, case ID or archived future answer enters evaluation. Full input identities, branch selections, child result hashes, terminal tree references and per-candidate counts are persisted. Every root is hash-bound in a separate cost-guard ledger event before the real routing decision. Model prediction computations are not actual oracle invocations; all actual MAP/tree labels are still independently paid.',
        cost_guard='Let weights be the positive integer weights in the current tree proof. Compare int(tree.optimal_cost) with sum(weights[c] * baseline_remaining_calls[c]) using exact integers. A feasible ancestor implies every counterfactual fixed-baseline terminal subset is depth-four separable; a noninformative query or infeasible terminal tree is therefore a correctness failure, not an excluded branch. Cost proof cache keys bind candidates, remaining MAP budget, sorted queried indices, depth, predictions hash, scores hash, selector hash and tree-compiler hash. All branches are retained.',
        compilation='Actual and counterfactual tree computations use the byte-identical H3bs OnlineCompiler and H3bl optimizer. Both operate only on candidate sets and immutable models. Counterfactual branches enumerate all possible model-consistent future labels; they do not precompile only the actual future branch from archived checkpoints. Every new tree proof and every baseline memo state is charged. Actual tree receipts and cost-root dependency receipts are logged before their first real query. No unrelated or unreferenced proof work is hidden.',
        expected_cost_property='The guard implies nonincrease under the prescribed posterior when it accepts. On rejection, the same next MAP query followed by this guarded rule also has no larger expected cost than its fixed-baseline continuation, by backward induction. This conditional optimization property and per-case identification equality are correctness properties. They do not imply a realized 2% finite-cohort reduction, a population effect size or calibration outside the declared model. See GUARD_LEMMA.md.',
        gates='Retain the weighted compiler, restriction, online cache, information-bound and archive-integrity gates. Add exact counterfactual parity against independent per-candidate fixed-baseline simulation for remaining MAP budgets 0,1,2,4. Fixed synthetic costs: acceptance 74 <= 82, rejection 215 > 119, and equality 2 == 2. Verify repeated cost-cache hits add no work. Prefix sharing must preserve every candidate cost; measured selector calls are reported. Runtime repeats the gates and retains their complete proof artifacts, with all compiler/counterfactual memo states and split evaluations in the aggregate limits. No cohort pilot outcomes are computed before freeze.',
        descriptive='Report MAP/tree call components, all guard accept/reject/tie counts, handoff timing, cache/node counts, CPU/wall costs and overlap charges. The original 10,355-call H3br policy remains the primary comparator. H3bs used 10,937 calls on the same examined cases; any comparison with it is descriptive. No case filtering, new draws, independent confirmation or changed accuracy endpoint.',
        source_sha256={str(path.relative_to(ROOT)):sha(path) for path in sources},source_data_sha256={rel:sha(ROOT/rel) for rel in sorted(set(inputs))},target_data_sha256={})
    p['budget']=dict(aggregate_CPU_seconds=600,wall_seconds=900,GPUs=0,max_memo_states_total=2000000,max_split_evaluations_total=50000000,max_integer_bits=100000,membership_calls=32768,planned_cases=4096,new_positive_appearances=0,historical_positive_appearances=32768,enforcement='Aggregate memo states include tree-compiler states plus counterfactual baseline memo entries; aggregate split evaluations include tree canonical alternatives plus counterfactual MAP partitions. Runtime scientific fixtures contribute the same components. CPU/wall limits include all computations, independent fixture checks, preparation, serialization and monitoring. Any cap, error, missing proof or correctness violation makes the whole study incomplete, retaining every planned case and paid call. No budget extension or reduced-scope claim.')
    assert sha(SRC/'policy.py')==sha(SRC.parent/'h3bs/policy.py') and sha(SRC/'compiler.py')==sha(SRC.parent/'h3bl/compiler.py') and sha(SRC/'weights.py')==sha(SRC.parent/'h3bl/weights.py')
    for name in ['selector.py','ledger.py']:assert sha(SRC/name)==sha(SRC.parent/'h3bm'/name)
    save(SRC/'protocol.json',p);print('FROZEN',sha(SRC/'protocol.json'),flush=True)


if __name__=='__main__':main()
